const DURATION_SECONDS = 30 * 60;
const $ = (id) => document.getElementById(id);
let candidate = {name:"", email:""};
let order = [...QUESTIONS];
let answers = {};
let current = 0;
let secondsLeft = DURATION_SECONDS;
let timerId = null;
let submitted = false;
let started = false;

const sectionNames = [...new Set(QUESTIONS.map(q => q.section))];
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
}
function fmtTime(s) {
  const m = Math.floor(s / 60), sec = s % 60;
  return `${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}`;
}
function show(id) {
  ["welcome","exam","results"].forEach(x => $(x).classList.toggle("hidden", x !== id));
}
function startExam(ev) {
  ev.preventDefault();
  const name = $("candidateName").value.trim();
  const email = $("candidateEmail").value.trim();
  if (!name || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    $("loginError").textContent = "Enter your name and a valid email address.";
    return;
  }
  candidate = {name, email};
  order = [...QUESTIONS];
  answers = {}; current = 0; secondsLeft = DURATION_SECONDS; submitted = false; started = true;
  $("candidateLabel").textContent = `${candidate.name} · ${candidate.email}`;
  show("exam");
  renderQuestion();
  updateStats();
  clearInterval(timerId);
  timerId = setInterval(() => {
    secondsLeft--;
    $("timer").textContent = fmtTime(secondsLeft);
    $("timer").classList.toggle("urgent", secondsLeft <= 300);
    if (secondsLeft <= 0) submitExam(true);
  }, 1000);
}
function filteredQuestions() {
  const filter = $("sectionFilter").value;
  return filter === "all" ? order : order.filter(q => q.section === filter);
}
function renderQuestion() {
  const list = filteredQuestions();
  if (!list.length) return;
  if (current >= list.length) current = list.length - 1;
  const q = list[current];
  $("sectionName").textContent = q.section;
  $("questionNumber").textContent = `Question ${q.id} of ${QUESTIONS.length}`;
  $("questionText").textContent = q.question;
  $("questionCount").textContent = `${current + 1} / ${list.length}`;
  $("options").innerHTML = q.options.map((opt, i) => `
    <button type="button" class="option ${answers[q.id] === i ? "selected" : ""}" data-option="${i}">
      <span class="option-letter">${String.fromCharCode(65+i)}</span><span>${escapeHtml(opt)}</span>
    </button>`).join("");
  $("options").querySelectorAll("[data-option]").forEach(btn => btn.addEventListener("click", () => {
    answers[q.id] = Number(btn.dataset.option);
    renderQuestion(); updateStats();
  }));
  $("prevBtn").disabled = current === 0;
  $("nextBtn").textContent = current === list.length - 1 ? "Review summary →" : "Next question →";
  renderNavigator();
}
function renderNavigator() {
  const list = filteredQuestions();
  $("navigator").innerHTML = list.map((q,i) => `
    <button class="nav-number ${i===current?"active":""} ${answers[q.id]!==undefined?"answered":""}" data-jump="${i}" aria-label="Question ${q.id}">${q.id}</button>`).join("");
  $("navigator").querySelectorAll("[data-jump]").forEach(btn => btn.addEventListener("click", () => {
    current = Number(btn.dataset.jump); renderQuestion();
  }));
}
function updateStats() {
  const count = Object.keys(answers).length;
  $("answeredCount").textContent = count;
  $("answeredCountMirror").textContent = count;
  $("unansweredCount").textContent = QUESTIONS.length - count;
  $("progressFill").style.width = `${count / QUESTIONS.length * 100}%`;
}
function nextQuestion() {
  const list = filteredQuestions();
  if (current < list.length - 1) { current++; renderQuestion(); }
  else openReview();
}
function previousQuestion() { if (current > 0) { current--; renderQuestion(); } }
function openReview() {
  const unanswered = QUESTIONS.length - Object.keys(answers).length;
  const ok = confirm(`Review before submitting?\nAnswered: ${Object.keys(answers).length} / ${QUESTIONS.length}\nUnanswered: ${unanswered}\n\nPress OK to submit and see your score, or Cancel to continue.`);
  if (ok) submitExam(false);
}
function submitExam(auto=false) {
  if (submitted) return;
  if (!auto && !confirm("Submit the assessment and view your results?")) return;
  submitted = true; clearInterval(timerId);
  let score = 0;
  QUESTIONS.forEach(q => { if (answers[q.id] === q.correctIndex) score++; });
  const pct = Math.round(score / QUESTIONS.length * 100);
  $("resultName").textContent = candidate.name;
  $("resultEmail").textContent = candidate.email;
  $("scoreBig").textContent = `${score} / ${QUESTIONS.length}`;
  $("scorePercent").textContent = `${pct}%`;
  $("correctResult").textContent = score;
  $("wrongResult").textContent = Object.keys(answers).length - score;
  $("unansweredResult").textContent = QUESTIONS.length - Object.keys(answers).length;
  $("resultMessage").textContent = auto ? "Time is up. Your answers have been submitted automatically." :
    pct >= 70 ? "Good work! Review the explanations to strengthen your knowledge." :
    "Keep practising. Review the explanations below and try again.";
  $("reviewList").innerHTML = QUESTIONS.map(q => {
    const selected = answers[q.id];
    const correct = selected === q.correctIndex;
    return `<article class="review-card ${selected===undefined?"unanswered":correct?"correct":"wrong"}">
      <div class="review-top"><span class="pill">${escapeHtml(q.section)}</span><span class="review-status">${selected===undefined?"Not answered":correct?"Correct":"Incorrect"}</span></div>
      <h3>${q.id}. ${escapeHtml(q.question)}</h3>
      <p><b>Your answer:</b> ${selected===undefined?"Not answered":escapeHtml(q.options[selected])}</p>
      <p class="correct-answer"><b>Correct answer:</b> ${escapeHtml(q.answer)}</p>
      <p class="explanation">${escapeHtml(q.explanation)}</p>
    </article>`;
  }).join("");
  show("results");
  window.scrollTo({top:0, behavior:"smooth"});
}
function restart() {
  clearInterval(timerId); answers={}; current=0; secondsLeft=DURATION_SECONDS; submitted=false; started=false;
  $("candidateName").value=candidate.name; $("candidateEmail").value=candidate.email;
  $("loginError").textContent="";
  show("welcome"); window.scrollTo({top:0, behavior:"smooth"});
}
function downloadResults() {
  const score = QUESTIONS.filter(q => answers[q.id] === q.correctIndex).length;
  const lines = [
    "ICICI Bank Model Assessment — Practice Result",
    "Independent practice website; not an official ICICI Bank portal.",
    `Candidate: ${candidate.name}`, `Email: ${candidate.email}`,
    `Score: ${score}/${QUESTIONS.length}`, `Percentage: ${Math.round(score/QUESTIONS.length*100)}%`, "",
    ...QUESTIONS.map(q => `${q.id}. ${q.question}\nYour answer: ${answers[q.id]===undefined?"Not answered":q.options[answers[q.id]]}\nCorrect answer: ${q.answer}\n`)
  ];
  const blob = new Blob([lines.join("\n")], {type:"text/plain;charset=utf-8"});
  const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = "ICICI-model-assessment-result.txt"; a.click(); URL.revokeObjectURL(a.href);
}
$("loginForm").addEventListener("submit", startExam);
$("prevBtn").addEventListener("click", previousQuestion);
$("nextBtn").addEventListener("click", nextQuestion);
$("submitBtn").addEventListener("click", () => openReview());
$("sectionFilter").addEventListener("change", () => { current=0; renderQuestion(); });
$("restartBtn").addEventListener("click", restart);
$("downloadBtn").addEventListener("click", downloadResults);
$("timer").textContent = fmtTime(DURATION_SECONDS);
